import{_ as r,o as e,c as t,a7 as n}from"./chunks/framework.CWfAgRyf.js";const f=JSON.parse(`{"title":"Forwarding ports in your router","description":"How to forward your server's port in your router. This is not needed if you're running Axolotl-PM on a VPS.","frontmatter":{"title":"Forwarding ports in your router","outline":"deep","description":"How to forward your server's port in your router. This is not needed if you're running Axolotl-PM on a VPS.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/connecting/portforward"}]]},"headers":[],"relativePath":"docs/connecting/portforward.md","filePath":"docs/connecting/portforward.md","lastUpdated":null}`),a={name:"docs/connecting/portforward.md"};function i(s,o,d,l,u,c){return e(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="forwarding-ports-in-your-router" tabindex="-1">Forwarding ports in your router <a class="header-anchor" href="#forwarding-ports-in-your-router" aria-label="Permalink to &quot;Forwarding ports in your router&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Note</p><p>If you’re running Axolotl-PM on a VPS (Virtual Private Server), you don’t need to do this.</p></div><p>Forwarding ports is needed when your server is behind a router (e.g. on a home WiFi or LAN), and you want to allow people who aren’t on your network to connect from outside using your public IP address.</p><h2 id="using-upnp" tabindex="-1">Using UPnP <a class="header-anchor" href="#using-upnp" aria-label="Permalink to &quot;Using UPnP&quot;">​</a></h2><p>Axolotl-PM can use UPnP (Universal Plug and Play) to forward ports for you, but it’s disabled by default.</p><p>UPnP can save you a lot of hassle manually portforwarding, so it’s worth giving it a shot before messing with your router settings.</p><p>You can try it by opening your <code>pocketmine.yml</code> and setting <code>upnp-forwarding</code> to <code>true</code>. Save the file and restart the server. On startup, the server should tell you in the logs whether it succeeded or not.</p><h2 id="forwarding-manually" tabindex="-1">Forwarding manually <a class="header-anchor" href="#forwarding-manually" aria-label="Permalink to &quot;Forwarding manually&quot;">​</a></h2><p>Unfortunately, every router has a different interface, so we can’t give a common set of instructions for portforwarding here.</p><p>Check <a href="http://portforward.com/english/routers/port_forwarding/routerindex.htm" target="_blank" rel="noreferrer">portforward.com</a> or use <a href="https://www.google.com" target="_blank" rel="noreferrer">Google</a> to find the instructions. Use the brand and type of your router as keywords.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>By default, Axolotl-PM listens on port <code>19132</code> for IPv4 connections, and <code>19133</code> for IPv6 connections.</p><p>These are the ports you’ll need to forward (unless you customised them in <code>server.properties</code>).</p></div>',11)])])}const h=r(a,[["render",i]]);export{f as __pageData,h as default};
